pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Cooler c;

    function setUp() public {
        c = new Cooler();
    }

    function _run(uint256 amount, uint256 rate) internal {
        vm.assume(true);
        uint256 interest0;
        try c.interestFor(amount, rate, 0) returns (uint256 __r) { interest0 = __r; } catch { return; }
        assertTrue(interest0 == 0);
    }

    function testFuzz_run(uint256 amount, uint256 rate) public {
        _run(amount, rate);
    }

    receive() external payable {}
}
